        // Anthropic API errors — what to do, not just the HTTP code. Never use the words "context" or
        // "too long" here: the agent loop reads those in a 400 as "prompt overflow" and compacts.
        ["anthropic.err.workspaceRequired"] = new() { ["en"] = "This API key isn't tied to one workspace, so every request has to name one. Put your Workspace ID (wrkspc_…) in the Workspace ID field — find it in Claude Console → Settings → Workspaces — or create a key scoped to a single workspace.", ["th"] = "API key นี้ไม่ได้ผูกกับ workspace จึงต้องระบุ workspace ทุกครั้ง — ใส่ Workspace ID (wrkspc_…) ในช่อง Workspace ID (ดูได้ที่ Claude Console → Settings → Workspaces) หรือสร้างคีย์ใหม่โดยเลือก workspace ตอนสร้าง" },
        ["anthropic.err.workspaceInvalid"] = new() { ["en"] = "That Workspace ID isn't valid, or this key has no access to it. Copy it exactly from Claude Console → Settings → Workspaces (it starts with wrkspc_).", ["th"] = "Workspace ID ไม่ถูกต้อง หรือคีย์นี้ไม่มีสิทธิ์ใน workspace นั้น — คัดลอก ID จาก Claude Console → Settings → Workspaces ให้ตรงทุกตัว (ขึ้นต้นด้วย wrkspc_)" },
        ["anthropic.err.badKey"] = new() { ["en"] = "The API key was rejected — it is wrong, expired, or disabled. Create a new one at platform.claude.com/settings/keys.", ["th"] = "API key ถูกปฏิเสธ — คีย์ผิด หมดอายุ หรือถูกปิดใช้งาน สร้างคีย์ใหม่ได้ที่ platform.claude.com/settings/keys" },
        ["anthropic.err.credit"] = new() { ["en"] = "The account is out of API credit. Add credit at platform.claude.com/settings/billing.", ["th"] = "เครดิต API หมด — เติมเครดิตได้ที่ platform.claude.com/settings/billing" },
        ["anthropic.err.model"] = new() { ["en"] = "Model {0} isn't available to this key. Pick another model, or press Test Connection to load the models this key can use.", ["th"] = "คีย์นี้ใช้โมเดล {0} ไม่ได้ — เลือกโมเดลอื่น หรือกด ทดสอบการเชื่อมต่อ เพื่อโหลดรายชื่อโมเดลที่คีย์นี้ใช้ได้" },
        ["anthropic.err.permission"] = new() { ["en"] = "This key isn't allowed to do that. Check the key's role and workspace in Claude Console.", ["th"] = "คีย์นี้ไม่มีสิทธิ์ทำรายการนี้ — ตรวจ role และ workspace ของคีย์ใน Claude Console" },
        ["anthropic.err.rateLimit"] = new() { ["en"] = "Rate limit reached — wait a moment and try again.", ["th"] = "ส่งคำขอถี่เกินกำหนด — รอสักครู่แล้วลองใหม่" },
        ["anthropic.err.overloaded"] = new() { ["en"] = "Anthropic's servers are busy or having a problem — try again shortly.", ["th"] = "เซิร์ฟเวอร์ Anthropic ไม่ว่างหรือมีปัญหา — ลองใหม่อีกครั้งในอีกสักครู่" },
        ["anthropic.err.refusal"] = new() { ["en"] = "Claude declined this request (safety filter). Rephrase it, or switch to another model.", ["th"] = "Claude ปฏิเสธคำขอนี้ (ตัวกรองความปลอดภัย) — ลองเรียบเรียงใหม่ หรือเปลี่ยนโมเดล" },
        ["anthropic.err.noKey"] = new() { ["en"] = "An API key is required.", ["th"] = "ต้องใส่ API key" },
        // Same idea for OpenAI / Gemini: {0} = provider name, {1} = URL or model
        ["api.err.badKey"] = new() { ["en"] = "{0} rejected the API key — it is wrong, expired, or revoked. Create a new one at {1}.", ["th"] = "{0} ปฏิเสธ API key — คีย์ผิด หมดอายุ หรือถูกยกเลิก สร้างคีย์ใหม่ได้ที่ {1}" },
        ["api.err.quota"] = new() { ["en"] = "The {0} account has no quota or credit left. Check billing at {1}.", ["th"] = "บัญชี {0} ไม่มีโควตาหรือเครดิตเหลือ — ตรวจการเรียกเก็บเงินได้ที่ {1}" },
        ["api.err.model"] = new() { ["en"] = "Model {1} isn't available to this {0} key (wrong name, retired, or not enabled). Pick another model, or press Test Connection to load the models this key can use.", ["th"] = "คีย์ {0} นี้ใช้โมเดล {1} ไม่ได้ (ชื่อผิด ถูกปิดแล้ว หรือไม่ได้เปิดสิทธิ์) — เลือกโมเดลอื่น หรือกด ทดสอบการเชื่อมต่อ เพื่อโหลดรายชื่อโมเดลที่คีย์นี้ใช้ได้" },
        ["api.err.permission"] = new() { ["en"] = "This {0} key isn't allowed to do that. Check the key's project and permissions.", ["th"] = "คีย์ {0} นี้ไม่มีสิทธิ์ทำรายการนี้ — ตรวจโปรเจกต์และสิทธิ์ของคีย์" },
        ["api.err.rateLimit"] = new() { ["en"] = "{0} rate limit reached — wait a moment and try again.", ["th"] = "ส่งคำขอถึง {0} ถี่เกินกำหนด — รอสักครู่แล้วลองใหม่" },
