        ["chat.spend.today"] = new() { ["en"] = "Today ${0}", ["th"] = "วันนี้ ${0}" },
        ["chat.spend.todayTip"] = new() { ["en"] = "What CluadeX spent today on paid APIs — every chat, kept across restarts (list price). The account's remaining credit is shown only on the provider's billing page: press Credit.", ["th"] = "ที่ CluadeX ใช้ไปวันนี้กับ API แบบเสียเงิน — ทุกแชท นับต่อเนื่องแม้เปิดโปรแกรมใหม่ (ราคาตามรายการ) ส่วนเครดิตคงเหลือของบัญชีดูได้ที่หน้า billing ของผู้ให้บริการเท่านั้น: กดปุ่ม เครดิต" },
        ["chat.estimate.text"] = new() { ["en"] = "≈ ${0}–{1}/step · ${2} ≈ {3}–{4} steps", ["th"] = "≈ ${0}–{1}/ขั้น · ${2} ≈ {3}–{4} ขั้น" },
        ["chat.estimate.textNoBudget"] = new() { ["en"] = "≈ ${0}–{1}/step", ["th"] = "≈ ${0}–{1}/ขั้น" },
        ["chat.estimate.tip"] = new() { ["en"] = "Estimate for {0} (list price ${1} in · ${2} out · ${3} cache read per MTok):\n• Step 1 ≈ ${4} — the prefix is written to the prompt cache: system prompt + tools ≈ {5:N0} tokens{6}, chat so far ≈ {7:N0}\n• Each later step ≈ ${8} early on, ≈ ${9} after ~40 steps — the prefix is read back at the cache price; the step's new content (≈ {10:N0} tokens) is written\n• The answer ≈ {11:N0} tokens a step ({12})\nThe estimate updates from what this session's runs really used. Lower effort or a cheaper model to spend less.", ["th"] = "ประมาณการสำหรับ {0} (ราคา ${1} ขาเข้า · ${2} ขาออก · ${3} อ่าน cache ต่อล้านโทเค็น):\n• ขั้นแรก ≈ ${4} — เขียนส่วนหัวลง cache: system prompt + เครื่องมือ ≈ {5:N0} โทเค็น{6} และแชทที่ผ่านมา ≈ {7:N0}\n• ขั้นถัดไป ≈ ${8} ช่วงต้น และ ≈ ${9} เมื่อผ่านไป ~40 ขั้น — ส่วนหัวอ่านจาก cache ในราคาถูก ส่วนเนื้อหาใหม่ของแต่ละขั้น (≈ {10:N0} โทเค็น) ถูกเขียนเพิ่ม\n• คำตอบ ≈ {11:N0} โทเค็นต่อขั้น ({12})\nตัวเลขจะปรับตามที่รอบจริงในเซสชันนี้ใช้ ลด effort หรือเลือกโมเดลที่ถูกกว่าเพื่อประหยัด" },
        ["chat.estimate.deferred"] = new() { ["en"] = " ({0} MCP tools load only when needed)", ["th"] = " (เครื่องมือ MCP {0} ตัวโหลดเฉพาะตอนใช้)" },
        ["chat.estimate.outEffort"] = new() { ["en"] = "effort {0}", ["th"] = "effort {0}" },
        ["chat.estimate.outMeasured"] = new() { ["en"] = "measured in this session", ["th"] = "วัดจากรอบจริงในเซสชันนี้" },
        ["chat.spend.summary"] = new() { ["en"] = "💸 This run: ${0} · {1} steps · ~${2}/step · {3:0}% of the prompt read from the cache · {4:N0} tokens out", ["th"] = "💸 รอบนี้ใช้ ${0} · {1} ขั้น · ~${2}/ขั้น · อ่านจาก cache {3:0}% · ตอบออก {4:N0} โทเค็น" },
        ["settings.card.chrome"] = new() { ["en"] = "Your Chrome", ["th"] = "Chrome ของคุณ" },
        ["settings.chromeBridge"] = new() { ["en"] = "Control Chrome with CluadeX's own extension (no Claude needed)", ["th"] = "ควบคุม Chrome ด้วย extension ของ CluadeX เอง (ไม่ต้องใช้ Claude)" },
        ["settings.chromeBridgeDesc"] = new() { ["en"] = "The browser tools work in your real Chrome with your logins, with any model, in a window of their own. Sites still ask once per chat. Click the CluadeX icon in Chrome to pause it at any time.", ["th"] = "เครื่องมือเบราว์เซอร์จะทำงานใน Chrome จริงของคุณพร้อมการล็อกอินของคุณ ใช้ได้กับทุกโมเดล และเปิดในหน้าต่างแยก แต่ละเว็บยังถามก่อนหนึ่งครั้งต่อแชต กดไอคอน CluadeX ใน Chrome เพื่อหยุดได้ทุกเมื่อ" },
        ["settings.chromeBridgeAdd"] = new() { ["en"] = "Add the extension to Chrome", ["th"] = "เพิ่ม extension เข้า Chrome" },
