        ["chromeBridge.status.steps"] = new() { ["en"] = "In Chrome: turn on Developer mode (top right), click Load unpacked, paste the folder path (already copied) and press Select Folder. Once is enough, but leave Developer mode on: Chrome turns the extension off without it.", ["th"] = "ใน Chrome: เปิด Developer mode (มุมขวาบน) กด Load unpacked วาง path ของโฟลเดอร์ (คัดลอกไว้ให้แล้ว) แล้วกด Select Folder ทำครั้งเดียวพอ แต่ต้องเปิด Developer mode ค้างไว้ ถ้าปิด Chrome จะปิด extension นี้ด้วย" },
        ["settings.chrome"] = new() { ["en"] = "Let the agent use your own Chrome (Claude in Chrome)", ["th"] = "ให้เอเจนต์ใช้ Chrome ของคุณ (Claude in Chrome)" },
        ["settings.chromeDesc"] = new() { ["en"] = "The agent opens tabs, reads, clicks and types in the Chrome you use — signed in where you are signed in (ChatGPT, GitHub …). Needs Claude Code and its Claude in Chrome extension; every action on a site asks first unless you allowed it.", ["th"] = "เอเจนต์เปิดแท็บ อ่าน คลิก และพิมพ์ใน Chrome ที่คุณใช้อยู่ — ล็อกอินไว้ที่ไหนก็ใช้ได้ที่นั่น (ChatGPT, GitHub …) ต้องมี Claude Code และส่วนขยาย Claude in Chrome; ทุกการกระทำบนเว็บจะถามก่อน เว้นแต่คุณอนุญาตไว้" },
        ["chrome.status.on"] = new() { ["en"] = "On — the agent has the Chrome tools", ["th"] = "เปิดอยู่ — เอเจนต์ใช้เครื่องมือ Chrome ได้" },
