        ["chrome.status.stopping"] = new() { ["en"] = "Stopping…", ["th"] = "กำลังปิด…" },
        ["chrome.status.startFailed"] = new() { ["en"] = "Could not start — open Chrome with the Claude extension signed in, then switch it on again (details on the MCP page)", ["th"] = "เปิดไม่สำเร็จ — เปิด Chrome ที่มีส่วนขยาย Claude ล็อกอินอยู่ แล้วเปิดสวิตช์ใหม่ (รายละเอียดดูที่หน้า MCP)" },
        ["chrome.status.noClaudeCode"] = new() { ["en"] = "Claude Code is not installed on this PC — install it and set up Claude in Chrome first", ["th"] = "เครื่องนี้ยังไม่มี Claude Code — ติดตั้งและตั้งค่า Claude in Chrome ก่อน" },
