        ["chrome.noClaudeCode"] = new() { ["en"] = "Claude Code (claude.exe) was not found — install it, or set its path in settings.json (ClaudeCodePathOverride)", ["th"] = "ไม่พบ Claude Code (claude.exe) — ติดตั้ง หรือกำหนด path ใน settings.json (ClaudeCodePathOverride)" },
