        ["chat.pause.tip"] = new() { ["en"] = "Pause: finish this step, then stop cleanly — Resume picks up from here (also after closing the app to update)", ["th"] = "หยุดชั่วคราว: ทำขั้นนี้ให้เสร็จแล้วหยุด — กดทำต่อเพื่อทำต่อจากจุดนี้ (ปิดโปรแกรมไปอัปเดตก่อนก็ได้)" },
