        ["chat.usage.cliTip"] = new() { ["en"] = "Claude Code runs on your Claude subscription; its usage limits are shown on claude.ai — press Credit.", ["th"] = "Claude Code ใช้แพ็กเกจ Claude ของคุณ · ดูโควต้าการใช้งานได้ที่ claude.ai — กด เครดิต" },
