        ["chat.effort"] = new() { ["en"] = "Effort", ["th"] = "ความพยายาม" },
        ["chat.effortTip"] = new() { ["en"] = "How hard the model works on each reply. auto = the model's own default; higher = deeper but slower and more tokens.\nUsed by Claude (API and Claude Code), OpenAI reasoning models and Gemini. A level a model doesn't have is rounded down.", ["th"] = "กำหนดว่าโมเดลจะคิดหนักแค่ไหนในแต่ละคำตอบ auto = ใช้ค่าเริ่มต้นของโมเดล · ยิ่งสูง ยิ่งคิดลึก แต่ช้าและใช้ token มากขึ้น\nใช้กับ Claude (API และ Claude Code), โมเดล reasoning ของ OpenAI และ Gemini · ถ้าโมเดลไม่มีระดับที่เลือก จะปัดลงเป็นระดับที่ใกล้ที่สุด" },

        // ── auto-wired page strings ──
        ["settings.browseTip"] = new() { ["en"] = "Browse", ["th"] = "เลือกโฟลเดอร์" },
