        ["settings.sessionFolderDesc"] = new() { ["en"] = "Where chat sessions are stored. Empty = the default under your user profile.", ["th"] = "ที่เก็บเซสชันแชท เว้นว่าง = ใช้ค่าเริ่มต้นใต้โปรไฟล์ผู้ใช้" },
        ["settings.thinkingDesc"] = new() { ["en"] = "Enable Claude's extended thinking mode for complex reasoning. Uses additional tokens for internal reasoning before responding.", ["th"] = "เปิดโหมดคิดลึกของ Claude สำหรับงานที่ซับซ้อน ใช้โทเค็นเพิ่มเพื่อคิดก่อนตอบ" },
        ["settings.cachingDesc"] = new() { ["en"] = "Caches the system prompt between requests — cheaper and faster repeated calls. Recommended.", ["th"] = "แคช system prompt ระหว่างคำขอ ทำให้ถูกลงและเร็วขึ้น · แนะนำให้เปิด" },
        ["settings.agentBehaviour"] = new() { ["en"] = "Agent Behaviour", ["th"] = "พฤติกรรมของเอเจนต์" },
