        ["settings.maxStepsTip"] = new() { ["en"] = "How many tool steps a run may take (0 = no limit). At the limit, a run still working asks once whether to go on.", ["th"] = "จำนวนขั้นที่เอเจนต์ทำได้ต่อรอบ (0 = ไม่จำกัด) · ถึงลิมิตแล้วงานยังไม่เสร็จ จะถามครั้งเดียวว่าทำต่อไหม" },
        ["settings.idleTimeout"] = new() { ["en"] = "Idle timeout (seconds)", ["th"] = "หมดเวลาเมื่อไม่มีการตอบ (วินาที)" },
        ["settings.idleTimeoutTip"] = new() { ["en"] = "Abort a request that sends nothing for this long (0 = never). Resets on every streamed token.", ["th"] = "ยกเลิกคำขอที่ไม่ส่งอะไรกลับมานานเท่านี้ (0 = ไม่ยกเลิก) · นับใหม่ทุกครั้งที่ได้รับ token" },
        ["settings.readBeforeEdit"] = new() { ["en"] = "Require reading a file before editing it", ["th"] = "ต้องอ่านไฟล์ก่อนจึงจะแก้ได้" },
        ["settings.readBeforeEditDesc"] = new() { ["en"] = "Blocks blind edits and edits to files that changed on disk since the last read (Claude Code behaviour).", ["th"] = "กันการแก้แบบไม่ได้อ่าน และกันการแก้ไฟล์ที่เปลี่ยนบนดิสก์หลังอ่านครั้งล่าสุด (แบบเดียวกับ Claude Code)" },
        ["settings.autoVerify"] = new() { ["en"] = "Build automatically after an edit and feed errors back", ["th"] = "บิลด์อัตโนมัติหลังแก้ไข แล้วส่ง error กลับให้ AI" },
        ["settings.autoVerifyDesc"] = new() { ["en"] = "Turns the compiler into the agent's oracle — it sees its own mistakes instead of claiming success.", ["th"] = "ให้คอมไพเลอร์เป็นตัวตัดสิน — AI เห็นความผิดพลาดของตัวเองแทนที่จะอ้างว่าสำเร็จ" },
        ["settings.planFirst"] = new() { ["en"] = "Plan first, then force a tool call", ["th"] = "วางแผนก่อน แล้วบังคับให้เรียกเครื่องมือ" },
        ["settings.midLoopReminder"] = new() { ["en"] = "Remind the agent of the goal mid-loop", ["th"] = "เตือนเป้าหมายกลางลูป" },
        ["settings.remindEvery"] = new() { ["en"] = "Remind every N steps", ["th"] = "เตือนทุก N ขั้น" },
        ["settings.escalate"] = new() { ["en"] = "Escalate to Claude when a local model gets stuck", ["th"] = "ส่งต่อให้ Claude เมื่อโมเดลในเครื่องติด" },
