        ["settings.learnInstincts"] = new() { ["en"] = "Learn instincts from finished sessions", ["th"] = "เรียนรู้สัญชาตญาณจากเซสชันที่จบแล้ว" },
        ["settings.brainRecall"] = new() { ["en"] = "Auto-recall from BrainX before answering", ["th"] = "ดึงความรู้จาก BrainX ก่อนตอบอัตโนมัติ" },
        ["settings.semanticSearch"] = new() { ["en"] = "Semantic (embedding) codebase search", ["th"] = "ค้นหาโค้ดเชิงความหมาย (embedding)" },
        ["settings.embeddingModel"] = new() { ["en"] = "Embedding model", ["th"] = "โมเดล embedding" },
