        ["settings.microKeep"] = new() { ["en"] = "Keep the last N turns intact", ["th"] = "เก็บ N รอบล่าสุดไว้ครบ" },
        ["settings.microTruncate"] = new() { ["en"] = "Trim older tool results to (characters)", ["th"] = "ตัดผลลัพธ์เครื่องมือเก่าเหลือ (ตัวอักษร)" },
        ["settings.localModelSection"] = new() { ["en"] = "Local Model — Tool Calling & Sampling", ["th"] = "โมเดลในเครื่อง — การเรียกเครื่องมือและการสุ่ม" },
        ["settings.nativeToolUse"] = new() { ["en"] = "Native tool calling for local models (llama-server / Ollama)", ["th"] = "เรียกเครื่องมือแบบ native สำหรับโมเดลในเครื่อง (llama-server / Ollama)" },
        ["settings.nativeToolUseDesc"] = new() { ["en"] = "Uses structured function-calling instead of the [ACTION:] text protocol. Much more reliable — turn OFF only if your model has no tool template.", ["th"] = "ใช้ function-calling แบบมีโครงสร้างแทนโปรโตคอลข้อความ [ACTION:] เสถียรกว่ามาก — ปิดเฉพาะเมื่อโมเดลไม่มี tool template" },
